-- ─────────────────────────────────────────────────────────────────────────────
-- Pick&Pay — R8: session code (an alternative to the QR)
-- ─────────────────────────────────────────────────────────────────────────────
--
--   * sessions.join_code: 6 characters from an alphabet with no look-alikes
--     (no 0/O, 1/I/L): 23456789ABCDEFGHJKMNPQRSTUVWXYZ, 31 characters,
--     31^6 = 887 503 681 codes. Shown as ABC-234.
--   * Generated by the server when the session is created (BEFORE INSERT
--     trigger), atomically: every code ever given is kept in
--     session_join_codes, which is never emptied, so an old code never leads
--     to another session — not after the session closes, not after it is
--     deleted. The client has no grant on the column, and the trigger keeps
--     a code once set.
--   * resolve_join_code(text): signed-in users only. Accepts lower case,
--     spaces and the hyphen (or none). Returns the session id; the app then
--     goes through join_preview exactly as with the QR (R7). At most 10 wrong
--     codes per user in 10 minutes; after that it answers rate_limited with
--     the seconds to wait.
--   * Backfill: every session not closed gets a code.

-- ── Codes ever given (never emptied) ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.session_join_codes (
  code       text PRIMARY KEY,
  session_id uuid NOT NULL,          -- no FK: the code outlives the session
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.session_join_codes ENABLE ROW LEVEL SECURITY;   -- no policies: server only
REVOKE ALL ON public.session_join_codes FROM anon, authenticated;

-- Wrong codes, per user (for the attempt limit). Kept for a day.
CREATE TABLE IF NOT EXISTS public.join_code_attempts (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id      uuid NOT NULL,
  attempted_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.join_code_attempts ENABLE ROW LEVEL SECURITY;   -- no policies: server only
REVOKE ALL ON public.join_code_attempts FROM anon, authenticated;
CREATE INDEX IF NOT EXISTS join_code_attempts_user_idx ON public.join_code_attempts (user_id, attempted_at);

CREATE OR REPLACE FUNCTION public.join_code_alphabet()
RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT '23456789ABCDEFGHJKMNPQRSTUVWXYZ'::text $$;
CREATE OR REPLACE FUNCTION public.join_code_max_failures()
RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT 10 $$;
CREATE OR REPLACE FUNCTION public.join_code_window_s()
RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT 600 $$;

-- A new code, registered for p_session_id. Uniform over the alphabet
-- (random bytes ≥ 248 are dropped so 31 divides evenly).
CREATE OR REPLACE FUNCTION public.new_join_code(p_session_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alpha text := public.join_code_alphabet();
  v_n     integer := length(public.join_code_alphabet());
  v_bytes bytea;
  v_code  text;
  v_got   text;
  b       integer;
  i       integer;
  tries   integer := 0;
BEGIN
  LOOP
    tries := tries + 1;
    IF tries > 20 THEN
      RAISE EXCEPTION 'Could not find a free session code' USING ERRCODE = '40001';
    END IF;
    v_code := '';
    v_bytes := extensions.gen_random_bytes(32);
    i := 0;
    WHILE length(v_code) < 6 AND i < 32 LOOP
      b := get_byte(v_bytes, i);
      i := i + 1;
      IF b < 248 THEN
        v_code := v_code || substr(v_alpha, (b % v_n) + 1, 1);
      END IF;
    END LOOP;
    CONTINUE WHEN length(v_code) < 6;
    INSERT INTO public.session_join_codes (code, session_id) VALUES (v_code, p_session_id)
    ON CONFLICT (code) DO NOTHING
    RETURNING code INTO v_got;
    IF v_got IS NOT NULL THEN
      RETURN v_got;
    END IF;
  END LOOP;
END;
$function$;
REVOKE ALL ON FUNCTION public.new_join_code(uuid) FROM PUBLIC, anon, authenticated;

-- ── The column ──────────────────────────────────────────────────────────────
ALTER TABLE public.sessions ADD COLUMN IF NOT EXISTS join_code text;
CREATE UNIQUE INDEX IF NOT EXISTS sessions_join_code_key ON public.sessions (join_code) WHERE join_code IS NOT NULL;
ALTER TABLE public.sessions DROP CONSTRAINT IF EXISTS sessions_join_code_format;
ALTER TABLE public.sessions ADD CONSTRAINT sessions_join_code_format
  CHECK (join_code IS NULL OR join_code ~ '^[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{6}$');

CREATE OR REPLACE FUNCTION public.set_session_join_code()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.join_code := public.new_join_code(NEW.id);
  ELSIF OLD.join_code IS NOT NULL THEN
    NEW.join_code := OLD.join_code;   -- a code never changes once given
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.set_session_join_code() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS set_session_join_code ON public.sessions;
CREATE TRIGGER set_session_join_code
  BEFORE INSERT OR UPDATE OF join_code ON public.sessions
  FOR EACH ROW EXECUTE FUNCTION public.set_session_join_code();

-- Members read it like the rest of the session (RLS decides the rows).
GRANT SELECT (join_code) ON public.sessions TO authenticated;

-- ── Backfill: sessions not closed ───────────────────────────────────────────
ALTER TABLE public.sessions DISABLE TRIGGER update_sessions_updated_at;
UPDATE public.sessions SET join_code = public.new_join_code(id)
WHERE status <> 'closed' AND join_code IS NULL;
ALTER TABLE public.sessions ENABLE TRIGGER update_sessions_updated_at;

-- ── Entering by code ────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.resolve_join_code(p_code text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_uid    uuid := auth.uid();
  v_norm   text;
  v_sid    uuid;
  v_fails  integer;
  v_oldest timestamptz;
  v_window interval := make_interval(secs => public.join_code_window_s());
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to join a session' USING ERRCODE = '42501';
  END IF;
  -- One check at a time per user, so parallel calls cannot slip past the limit.
  PERFORM pg_advisory_xact_lock(hashtextextended('join_code:' || v_uid::text, 0));
  DELETE FROM public.join_code_attempts WHERE user_id = v_uid AND attempted_at < now() - interval '1 day';

  SELECT count(*), min(attempted_at) INTO v_fails, v_oldest
  FROM public.join_code_attempts
  WHERE user_id = v_uid AND attempted_at > now() - v_window;
  IF v_fails >= public.join_code_max_failures() THEN
    RETURN jsonb_build_object('result', 'rate_limited',
      'retry_after_s', greatest(1, ceil(extract(epoch FROM (v_oldest + v_window - now())))::int));
  END IF;

  v_norm := upper(regexp_replace(coalesce(p_code, ''), '[[:space:]-]', '', 'g'));
  IF v_norm ~ ('^[' || public.join_code_alphabet() || ']{6}$') THEN
    SELECT id INTO v_sid FROM public.sessions WHERE join_code = v_norm;
  END IF;
  IF v_sid IS NULL THEN
    INSERT INTO public.join_code_attempts (user_id) VALUES (v_uid);
    RETURN jsonb_build_object('result', 'invalid',
      'attempts_left', public.join_code_max_failures() - v_fails - 1);
  END IF;
  RETURN jsonb_build_object('result', 'found', 'session_id', v_sid);
END;
$function$;
REVOKE ALL ON FUNCTION public.resolve_join_code(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.resolve_join_code(text) TO authenticated;
